package com.fitforge.cardio;

import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.util.List;
import java.time.LocalDate;

@Service public class CardioService {
    private final CardioRepository repo;private final CardioGoalRepository goals; public CardioService(CardioRepository repo,CardioGoalRepository goals){this.repo=repo;this.goals=goals;}
    public List<CardioDtos.Session> list(String email){return repo.findByUserEmailOrderBySessionDateDesc(email).stream().map(this::dto).toList();}
    @Transactional public CardioDtos.Session create(String email,CardioDtos.Create c){if(c.staminaScore()!=null&&c.staminaScore()>100)throw new IllegalArgumentException("staminaScore must be between 0 and 100");String activity=c.activity()==null?"RUNNING":c.activity().trim().toUpperCase(java.util.Locale.ROOT).replace(' ','_');if(activity.equals("JOGGING"))activity="INDOOR_JOGGING";if(!activity.equals("RUNNING")&&!activity.equals("INDOOR_JOGGING"))throw new IllegalArgumentException("activity must be RUNNING or INDOOR_JOGGING");return dto(repo.save(new CardioSession(email,new CardioDtos.Create(c.distanceKm(),c.durationMinutes(),c.caloriesBurned(),c.staminaScore(),c.sessionDate(),activity,c.notes()))));}
    @Transactional public void delete(String email,Long id){repo.delete(repo.findByIdAndUserEmail(id,email).orElseThrow(()->new IllegalArgumentException("Cardio session not found")));}
    @Transactional public CardioDtos.Goal putGoal(String email,CardioDtos.GoalInput i){if(i.targetDistanceKm()==null&&i.targetPaceMinPerKm()==null&&i.targetTimeSeconds()==null)throw new IllegalArgumentException("Provide a distance, pace, or time target");var g=goals.findByUserEmailAndGoalNameIgnoreCase(email,i.goalName()).orElseGet(()->new CardioGoal(email,i));g.update(i);return goalDto(g);}
    @Transactional public List<CardioDtos.Goal> goals(String email){return goals.findByUserEmailOrderByGoalNameAsc(email).stream().map(this::goalDto).toList();}
    private CardioDtos.Goal goalDto(CardioGoal g){var history=repo.findByUserEmailOrderBySessionDateDesc(g.getUserEmail());double maxDistance=history.stream().mapToDouble(CardioSession::getDistanceKm).max().orElse(0);var qualifying=history.stream().filter(s->g.getTargetDistanceKm()==null||s.getDistanceKm()>=g.getTargetDistanceKm()).toList();double bestPace=qualifying.stream().mapToDouble(CardioSession::getPaceMinPerKm).min().orElse(history.stream().mapToDouble(CardioSession::getPaceMinPerKm).min().orElse(0));int bestTime=qualifying.stream().mapToInt(s->(int)Math.round(s.getPaceMinPerKm()*(g.getTargetDistanceKm()==null?s.getDistanceKm():g.getTargetDistanceKm())*60)).min().orElse(0);boolean distanceMet=g.getTargetDistanceKm()==null||history.stream().anyMatch(s->s.getDistanceKm()>=g.getTargetDistanceKm());boolean paceMet=g.getTargetPaceMinPerKm()==null||bestPace>0&&bestPace<=g.getTargetPaceMinPerKm();boolean timeMet=g.getTargetTimeSeconds()==null||bestTime>0&&bestTime<=g.getTargetTimeSeconds();boolean met=distanceMet&&paceMet&&timeMet;LocalDate today=LocalDate.now();boolean missed=today.isAfter(g.getOriginalDeadline())&&!met;long late=missed?java.time.temporal.ChronoUnit.DAYS.between(g.getOriginalDeadline(),today):0;double nextDistance=g.getTargetDistanceKm()!=null&&maxDistance<g.getTargetDistanceKm()?Math.min(g.getTargetDistanceKm(),Math.max(.5,maxDistance+.5)):maxDistance;double nextPace=bestPace==0?0:Math.round(bestPace*.99*100.0)/100.0;if(missed&&!g.getRevisedDeadline().isAfter(today)){g.reviseDeadline(today.plusDays(distanceMet?21:42));goals.save(g);}String advice=missed?"Target deadline missed; a gradual deadline reforecast is set. Progress with easy sessions and avoid compensatory high-volume cardio.":"Build easy distance first; consider only a small pace improvement after recovery and comfortable completion.";return new CardioDtos.Goal(g.getId(),g.getGoalName(),g.getTargetDistanceKm(),g.getTargetPaceMinPerKm(),g.getTargetTimeSeconds(),g.getOriginalDeadline(),g.getRevisedDeadline(),maxDistance,bestPace,bestTime,met,missed,late,nextDistance,nextPace,advice,history.stream().limit(10).map(this::dto).toList());}
    private CardioDtos.Session dto(CardioSession e){return new CardioDtos.Session(e.getId(),e.getActivity(),e.getDistanceKm(),e.getDurationMinutes(),e.getPaceMinPerKm(),e.getCaloriesBurned(),e.getStaminaScore(),e.getSessionDate(),e.getNotes());}
}
